grid = []
for r in range(16):
    row = [0] * 16
    # (6,9,8) pattern
    if 4 + r < 16:
        row[4 + r] = 6
    if 5 + r < 16:
        row[5 + r] = 9
    if 6 + r < 16:
        row[6 + r] = 8
    # 5 pattern  
    if r >= 9 and r - 9 < 16:
        row[r - 9] = 5
    grid.append(row)

print(grid)

